@Test
public void testCombinations() throws Exception {
    check(new String[] {}, "");
    check(new String[] { "--none", "-0" }, // Canonical form
    "-0 -0");
    check(new String[] { "--one=a", "--one", "A", "-1b", "-1=c", "-1", "d" }, "-1=[a] -1=[A] -1=[b] -1=[c] -1=[d]");
    check(new String[] { "-2n=v", "-2", "N=V" }, "-2=[n, v] -2=[N, V]");
    check(new String[] { "--two=n=v", "--two", "N=V" }, "-2=[n, v] -2=[N, V]");
    // Test optional arguments
    check(new String[] { "-?", // Separate argument
    "A", "-?=B", "-?C", "-?" }, "-? [A] -?=[B] -?=[C] -?");
    check(new String[] { // OK
    "--optional=A", // should treat B as separate
    "--optional", // should treat B as separate
    "B", // Should have no arg
    "--optional" }, "-?=[A] -? [B] -?");
}

