@Test
public void testRemoveSlashDotDot() {
    assertEquals("/path/", ConversionUtils.removeSlashDotDot("/path/"));
    assertEquals("http://host/", ConversionUtils.removeSlashDotDot("http://host/"));
    assertEquals("http://host/one", ConversionUtils.removeSlashDotDot("http://host/one"));
    assertEquals("/two", ConversionUtils.removeSlashDotDot("/one/../two"));
    assertEquals("http://host:8080/two", ConversionUtils.removeSlashDotDot("http://host:8080/one/../two"));
    assertEquals("http://host:8080/two/", ConversionUtils.removeSlashDotDot("http://host:8080/one/../two/"));
    assertEquals("http://usr@host:8080/two/", ConversionUtils.removeSlashDotDot("http://usr@host:8080/one/../two/"));
    assertEquals("http://host:8080/two/?query#anchor", ConversionUtils.removeSlashDotDot("http://host:8080/one/../two/?query#anchor"));
    assertEquals("one", ConversionUtils.removeSlashDotDot("one/two/.."));
    assertEquals("../../path", ConversionUtils.removeSlashDotDot("../../path"));
    assertEquals("/", ConversionUtils.removeSlashDotDot("/one/.."));
    assertEquals("/", ConversionUtils.removeSlashDotDot("/one/../"));
    assertEquals("/?a", ConversionUtils.removeSlashDotDot("/one/..?a"));
    assertEquals("http://host/one", ConversionUtils.removeSlashDotDot("http://host/one/../one"));
    assertEquals("http://host/one/two", ConversionUtils.removeSlashDotDot("http://host/one/two/../../one/two"));
    assertEquals("http://host/..", ConversionUtils.removeSlashDotDot("http://host/.."));
    assertEquals("http://host/../abc", ConversionUtils.removeSlashDotDot("http://host/../abc"));
}

@Test
public void testsanitizeUrl() throws Exception {
    // normal, no encoding needed
    testSanitizeUrl("http://localhost/", "http://localhost/");
    // pipe needs encoding
    testSanitizeUrl("http://localhost/a/b/c%7Cd", "http://localhost/a/b/c|d");
    // already encoded
    testSanitizeUrl("http://localhost:8080/%5B%5D", "http://localhost:8080/%5B%5D");
    //already encoded
    testSanitizeUrl("http://localhost:8080/?%5B%5D", "http://localhost:8080/?%5B%5D");
    testSanitizeUrl("http://localhost:8080/?!£$*():@~;'%22%25%5E%7B%7D[]%3C%3E%7C%5C#", // unencoded query
    "http://localhost:8080/?!£$*():@~;'\"%^{}[]<>|\\#");
    testSanitizeUrl("http://localhost:8080/?!£$*():@~;'%22%25%5E%7B%7D[]%3C%3E%7C%5C#", // encoded
    "http://localhost:8080/?!£$*():@~;'%22%25%5E%7B%7D[]%3C%3E%7C%5C#");
    testSanitizeUrl("http://localhost:8080/!£$*():@~;'%22%25%5E%7B%7D%5B%5D%3C%3E%7C%5C#", // unencoded path
    "http://localhost:8080/!£$*():@~;'\"%^{}[]<>|\\#");
    testSanitizeUrl("http://localhost:8080/!£$*():@~;'%22%25%5E%7B%7D%5B%5D%3C%3E%7C%5C#", // encoded
    "http://localhost:8080/!£$*():@~;'%22%25%5E%7B%7D%5B%5D%3C%3E%7C%5C#");
    testSanitizeUrl("http://localhost/?%2525%255B%255D!@$%25%5E*()#", "http://localhost/?%25%5B%5D!@$%^*()#");
    testSanitizeUrl("http://localhost/?%2525%255B%255D!@$%25%5E*()#", "http://localhost/?%2525%255B%255D!@$%25%5E*()#");
    testSanitizeUrl("http://localhost/%255B%255D?[]!@$%25%5E*()#", "http://localhost/%5B%5D?[]!@$%^*()#");
    testSanitizeUrl("http://localhost/%255B%255D?[]!@$%25%5E*()#", "http://localhost/%255B%255D?[]!@$%25%5E*()#");
    testSanitizeUrl("http://localhost/IqGo6EM1JEVZ+MSRJqUSo@qhjVMSFBTs/37/0/1", "http://localhost/IqGo6EM1JEVZ+MSRJqUSo@qhjVMSFBTs/37/0/1");
    testSanitizeUrl("http://localhost/test?getItem=%7BsomeID%7D", "http://localhost/test?getItem={someID}");
}

