@Test
public void testopen() throws Exception {
    try {
        FS.readLine("test");
        fail("Expected IOException");
    } catch (IOException ignored) {
    }
    try {
        FS.write("test", "");
        fail("Expected IOException");
    } catch (IOException ignored) {
    }
    assertFalse("Should not have any files open", FS.filesOpen());
    // Unrecognised files are ignored
    FS.closeFile("xxx");
    assertFalse("Should not have any files open", FS.filesOpen());
    String infile = findTestPath("testfiles/test.csv");
    // Does not open file
    FS.reserveFile(infile);
    assertFalse("Should not have any files open", FS.filesOpen());
    assertEquals("a1,b1,c1,d1", FS.readLine(infile));
    assertTrue("Should have some files open", FS.filesOpen());
    assertNotNull(FS.readLine(infile));
    assertNotNull(FS.readLine(infile));
    assertNotNull(FS.readLine(infile));
    // Re-read 1st line
    assertEquals("a1,b1,c1,d1", FS.readLine(infile));
    assertNotNull(FS.readLine(infile));
    try {
        // should not be able to write to it ...
        FS.write(infile, "");
        fail("Expected IOException");
    } catch (IOException ignored) {
    }
    // does not remove the entry
    FS.closeFile(infile);
    assertFalse("Should not have any files open", FS.filesOpen());
    // Re-read 1st line
    assertEquals("a1,b1,c1,d1", FS.readLine(infile));
    assertTrue("Should have some files open", FS.filesOpen());
    // removes all entries
    FS.closeFiles();
    assertFalse("Should not have any files open", FS.filesOpen());
    try {
        FS.readLine(infile);
        fail("Expected IOException");
    } catch (IOException ignored) {
    }
    infile = findTestPath("testfiles/test.csv");
    // Does not open file
    FS.reserveFile(infile);
    assertFalse("Should not have any files open", FS.filesOpen());
    assertEquals("a1,b1,c1,d1", FS.readLine(infile));
    try {
        FS.setBasedir("x");
        fail("Expected IllegalStateException");
    } catch (IllegalStateException ignored) {
    }
    FS.closeFile(infile);
    FS.setBasedir("y");
    FS.closeFiles();
}

